    "guide.smartStudyTitle": "Ақылды оқу",
    "guide.smartStudyBody": "Жүйе қандай карточкаларды қайталау керегін анықтайды. Әлсіз, мерзімі өткен және жаңа карточкалар алдымен беріледі.",
    "guide.smartStep1": "Жүйе сіздің прогресіңізді бақылайды",
    "guide.smartStep2": "Әлсіз және мерзімі өткен карточкалар бірінші",
    "guide.smartStep3": "Уақыт аралығын арттыру — материалды терең есте сақтау",
    "guide.pomodoroTitle": "Помодоро таймер",
    "guide.pomodoroBody": "Жұмыс уақыты + үзіліс циклдері. Шоғырлануды және өнімділікті арттырады.",
    "guide.pomodoroStep1": "Алдын ала орнату таңдаңыз: 15/5, 25/5 немесе 50/10",
    "guide.pomodoroStep2": "Таймер автоматты басталады. Жұмыс → үзіліс",
    "guide.pomodoroStep3": "Аяқтағанда сессия қорытындысы көрсетіледі",
    "guide.gamificationTitle": "Серия, XP және жетістіктер",
    "guide.gamificationBody": "Оқу процесін қызықты ету. Күнделікті серия ұстаңыз, XP жинап, жетістіктерді ашыңыз.",
    "guide.streakTitle": "Серия",
    "guide.streakBody": "Күн сайын оқып, серияңызды үзбеңіз.",
    "guide.xpTitle": "XP және деңгей",
    "guide.xpBody": "Дұрыс жауаптар XP береді. XP жинап, деңгейіңізді көтеріңіз.",
    "guide.achievementsTitle": "Жетістіктер",
    "guide.achievementsBody": "Белгілі мақсаттарға жетіп, белгілер алыңыз.",
    "guide.leaderboardTitle": "Көшбасшылар тақтасы",
    "guide.leaderboardBody": "Басқа пайдаланушылармен жарысыңыз. Күнделік, апталық және жалпы рейтинг.",
    "guide.leaderboardStep1": "Оқу нәтижелеріңіз автоматты есептеледі",
    "guide.leaderboardStep2": "Ұпайлар: оқу уақыты, дұрыс жауаптар, аяқталған сессиялар",
    "guide.leaderboardStep3": "Топ-20 көшбасшыны көріңіз",
    "guide.profileSettingsTitle": "Профиль және баптаулар",
    "guide.profileSettingsBody": "Профиліңізді жаңартып, қосымша параметрлерін реттеңіз.",
    "guide.profileTitle": "Профиль",
    "guide.profileBody": "Оқу статистикаңыз, жетістіктеріңіз және белсенділігіңіз.",
    "guide.settingsTitle": "Баптаулар",
    "guide.settingsBody": "Тіл, тема, помодоро уақыты, дыбыстар.",
    "guide.ctaTitle": "Дайынсыз ба?",
    "guide.ctaBody": "Қазір оқуды бастап, білім деңгейіңізді көтеріңіз!",
    "guide.ctaStart": "Оқуды бастау",
    "guide.ctaCreate": "Жинақ құру",
    "onboarding.step1Title": "StudyWithRaissov-ға қош келдіңіз!",
    "onboarding.step1Body": "Flashcard жинақтарын құрып, тест жасап, ақылды оқу жүйесімен білім алыңыз.",
    "onboarding.step2Title": "Жинақ құрыңыз",
    "onboarding.step2Body": "Термин мен анықтама жұптарын қосыңыз. Тақырыптар бойынша ұйымдастырыңыз.",
    "onboarding.step3Title": "Үш режимде оқыңыз",
    "onboarding.step3Body": "Карточкаларды аударыңыз, тест тапсырыңыз немесе жауапты жазыңыз. Ақылды оқу жүйесі сізге не қайталау керегін көрсетеді.",
    "onboarding.step4Title": "Помодоро таймерімен үйреніңіз",
    "onboarding.step4Body": "Жұмыс + үзіліс циклдерімен шоғырланыңыз. Сессия аяғында нәтижелеріңізді көріңіз.",
    "onboarding.step5Title": "XP жинап, жарысыңыз!",
    "onboarding.step5Body": "Күндік серия ұстаңыз, XP жинаңыз, жетістіктер ашыңыз және көшбасшылар тақтасында орын алыңыз.",
