    "lp.faq.a3": "500 флэшкарта, күнделікті 1 AI сұрау, 3 mock тест және базалық кітапхана. Бұл — платформаны сынап көруге жеткілікті.",
    "lp.faq.q4": "AI көмекші қалай жұмыс жасайды?",
    "lp.faq.a4": "Эссеңді жазып жібересің — AI оны IELTS критерийлері бойынша тексеріп, нақты қателеріңді көрсетеді. Сөйлеу жазбасы үшін де солай: дауысыңды жазып жібересің, AI айтылым мен грамматикаңды талдайды.",
    "lp.faq.q5": "Қазақ тілі қолдау көрсетіле ме?",
    "lp.faq.a5": "Иә, барлық интерфейс және түсіндірмелер қазақ тілінде. Раиссов ағай дәрістерін де негізінен қазақша өткізеді.",
    "lp.faq.q6": "Жазылудан бас тартуға бола ма?",
    "lp.faq.a6": "Иә, кез келген уақытта. Қосымша төлем жоқ. Кабинетіңде бір батырмамен.",
