    "lp.faq.eyebrow": "Частые вопросы",
    "lp.faq.title": "Есть вопросы? Мы ответили",
    "lp.faq.q1": "StudyWithRaissov — что это за платформа?",
    "lp.faq.a1": "Это онлайн-платформа для подготовки к IELTS. Внутри — флэшкарты, AI помощник, mock тесты и уроки преподавателя Раисова. Работает на трёх языках: казахский, русский, английский.",
    "lp.faq.q2": "Сколько времени нужно для подготовки к IELTS?",
    "lp.faq.a2": "В среднем — 3 месяца. Но это зависит от твоего начального уровня. После регистрации короткий тест точно рассчитает срок.",
    "lp.faq.q3": "Что входит в бесплатный тариф?",
    "lp.faq.a3": "500 флэшкарт, 1 AI запрос в день, 3 mock теста и базовая библиотека. Этого достаточно, чтобы попробовать платформу.",
    "lp.faq.q4": "Как работает AI помощник?",
    "lp.faq.a4": "Напиши эссе — AI проверит его по критериям IELTS и точно укажет ошибки. То же для речи: запиши голос, AI проанализирует произношение и грамматику.",
    "lp.faq.q5": "Поддерживается ли русский язык?",
    "lp.faq.a5": "Да, весь интерфейс и пояснения на русском. Преподаватель Раисов также проводит уроки на русском языке.",
    "lp.faq.q6": "Можно ли отменить подписку?",
    "lp.faq.a6": "Да, в любое время. Без дополнительных платежей. Одна кнопка в личном кабинете.",
