    "lp.faq.eyebrow": "FAQ",
    "lp.faq.title": "Have questions? We have answers",
    "lp.faq.q1": "What is StudyWithRaissov?",
    "lp.faq.a1": "An online platform for IELTS prep. It includes flashcards, an AI tutor, mock tests, and lessons from Mr. Raissov. Available in three languages: Kazakh, Russian, English.",
    "lp.faq.q2": "How long does IELTS prep take?",
    "lp.faq.a2": "3 months on average — but it depends on your starting level. After signup, a short test estimates an exact timeline for you.",
    "lp.faq.q3": "What does the free plan include?",
    "lp.faq.a3": "500 flashcards, 1 AI request per day, 3 mock tests, and the basic library. Plenty to try the platform.",
    "lp.faq.q4": "How does the AI tutor work?",
    "lp.faq.a4": "Write an essay — the AI checks it against IELTS criteria and points out exact mistakes. Same for speaking: record your voice and the AI analyzes pronunciation and grammar.",
    "lp.faq.q5": "Is the platform in English too?",
    "lp.faq.a5": "Yes — the entire interface, lessons, and explanations are available in English, alongside Kazakh and Russian.",
    "lp.faq.q6": "Can I cancel my subscription?",
    "lp.faq.a6": "Yes — anytime. No extra fees. One button in your account.",
